Object.assign(TEXT.de,{"courseOpen": "Für den Kurs: In Kontakt bleiben", "courseEyebrow": "KURS · FREIWILLIGE KONTAKTLISTE", "courseTitle": "Bleibt in Kontakt!", "courseInfo": "Sabrina hat uns ans Herz gelegt, in Kontakt zu bleiben. Deshalb sammle ich freiwillige Angaben für eine Excel-Kontaktliste, die alle Teilnehmenden unseres Kurses erhalten. Du entscheidest selbst, welche Felder du ausfüllst. Alle eingetragenen Angaben – auch Adresse, GPS und „Sonstiges“, falls angegeben – sollen in diese Liste aufgenommen werden.", "courseSendInfo": "„E-Mail vorbereiten“ zeigt dir zuerst die Nachricht. Prüfe die Angaben und öffne dann dein Mailprogramm. Erst dort sendest du selbst ab.", "courseFirst": "Vorname", "courseLast": "Nachname", "courseTown": "Wohnort", "courseLocationHelp": "Alle Angaben sind freiwillig. Du kannst einzelne Felder ausfüllen und den Rest leer lassen.", "courseGpsButton": "GPS-Standort übernehmen – freiwillig", "courseGpsLoading": "Standort wird ermittelt …", "courseGpsClear": "GPS entfernen", "courseGpsAccuracy": "Genauigkeit laut Gerät: ca. {n} m", "courseGpsPrompt": "Bitte erlaube den Standortzugriff im Browser, wenn du GPS nutzen möchtest.", "courseGpsUnavailable": "GPS wird hier nicht unterstützt. Du kannst andere Felder ausfüllen oder GPS weglassen.", "courseGpsSuccess": "Standort übernommen. Er wird nur bei deiner Bestätigung und deinem E-Mail-Versand für die Kursliste mitgeteilt.", "courseGpsDenied": "Standortfreigabe abgelehnt. GPS bleibt leer; du kannst das Formular trotzdem ohne GPS verwenden.", "courseGpsFailed": "Standort konnte nicht ermittelt werden. Du kannst es erneut versuchen oder GPS weglassen.", "coursePrepare": "E-Mail vorbereiten", "courseClose": "Fenster schließen", "courseRecipient": "Empfänger", "courseRequiredNote": "Alle Datenfelder sind freiwillig. Für die Aufnahme in die Kursliste bestätige bitte die Weitergabe unten.", "courseDraftLabel": "Deine vorbereitete Nachricht", "courseOpenMail": "Im Mailprogramm öffnen", "courseDraftNote": "Die Nachricht ist nur vorbereitet. Öffne dein Mailprogramm, prüfe die Angaben und sende selbst ab. Hier wird keine Versandbestätigung angezeigt. Falls sich kein Mailprogramm öffnet, kannst du die Nachricht kopieren und selbst an info@mlinner-software.de senden.", "courseTo": "An", "courseSubject": "Betreff", "courseEmailSubject": "Kurs – freiwillige Excel-Kontaktliste | Rendezora", "courseEmailGreeting": "Hallo,", "courseEmailIntro": "Bitte übernimm die folgenden freiwillig angegebenen Daten in die Kontaktliste unseres Kurses:", "courseEmailBye": "Viele Grüße", "courseRequired": "Bitte ausfüllen.", "courseNeedLocation": "Bitte Wohnort/PLZ eingeben oder freiwillig GPS übernehmen.", "courseGpsHelp": "Dein Browser fragt nach deiner Erlaubnis. Prüfe die Koordinaten vor dem E-Mail-Versand. Du kannst sie jederzeit aus dem Formular entfernen. Es gibt keinen automatischen Standortabruf.", "courseDataTitle": "Was passiert mit meinen Angaben?", "courseDataInfo": "Diese Angaben werden für die freiwillige Kontaktliste unseres Kurses gesammelt. Mit deiner Bestätigung dürfen alle ausgefüllten Felder einschließlich Adresse, GPS und „Sonstiges“ in die Excel-Datei übernommen und an die Kursgruppe weitergegeben werden. Das Formular übernimmt die Daten zunächst nur in einen lokalen E-Mail-Entwurf; es trägt sie nicht automatisch in die Karte oder Teilnehmerliste ein. Beim Schließen dieses Fensters werden die Formulareingaben entfernt. Nach dem E-Mail-Versand können Kopien in Postfächern und später bei den Empfängern der Excel-Datei verbleiben. Bei Fragen oder einem Löschwunsch wende dich an info@mlinner-software.de. Bereits weitergegebene Dateikopien werden nicht automatisch zurückgerufen.", "courseEmail": "E-Mail-Adresse", "coursePhone": "Telefon / Mobil", "courseStreet": "Straße", "courseHouse": "Hausnummer", "coursePostal": "Postleitzahl", "courseCountry": "Land", "courseOther": "Sonstiges", "courseOtherHelp": "Hier kannst du ergänzen, was du mit der Kursgruppe teilen möchtest. Bis zu 1.000 Zeichen.", "courseConsent": "Ich möchte in die freiwillige Excel-Kontaktliste aufgenommen werden. Ich bin damit einverstanden, dass alle von mir hier angegebenen Daten – einschließlich Adresse, GPS und „Sonstiges“, soweit ausgefüllt – an alle Teilnehmenden unseres Kurses weitergegeben werden.", "courseConsentTitle": "Aufnahme in die Kontaktliste", "courseConsentHelp": "Die Bestätigung ist nicht vorausgewählt. Ohne Bestätigung wird keine Nachricht vorbereitet.", "courseNeedEntry": "Bitte mindestens eine freiwillige Angabe eintragen.", "courseNeedConsent": "Bitte bestätige die Weitergabe innerhalb unseres Kurses.", "courseConsentEmail": "Bestätigung zur Aufnahme und Weitergabe"});
Object.assign(TEXT.en,{"courseOpen": "For the course: stay in touch", "courseEyebrow": "COURSE · OPTIONAL CONTACT LIST", "courseTitle": "Stay in touch!", "courseInfo": "Sabrina encouraged us to stay in touch. I am collecting optional details for an Excel contact list that everyone in our course will receive. You decide which fields to fill in. All details you enter – including your address, GPS and “Other information”, if provided – are intended for this list.", "courseSendInfo": "“Prepare email” first shows you the message. Review your details, then open your email app. You send the email yourself from there.", "courseFirst": "First name", "courseLast": "Last name", "courseTown": "Town / city", "courseLocationHelp": "Every field is optional. Fill in the details you want to share and leave the rest blank.", "courseGpsButton": "Use GPS location – optional", "courseGpsLoading": "Finding your location …", "courseGpsClear": "Remove GPS", "courseGpsAccuracy": "Device-reported accuracy: approx. {n} m", "courseGpsPrompt": "Allow location access in your browser if you would like to use GPS.", "courseGpsUnavailable": "GPS is not supported here. You can fill in other fields or leave GPS blank.", "courseGpsSuccess": "Location added. It is only shared for the course list when you confirm and send your email.", "courseGpsDenied": "Location access declined. GPS stays blank; you can still use the form without it.", "courseGpsFailed": "Your location could not be found. You can try again or leave GPS blank.", "coursePrepare": "Prepare email", "courseClose": "Close window", "courseRecipient": "Recipient", "courseRequiredNote": "All data fields are optional. Please confirm sharing below to join the course contact list.", "courseDraftLabel": "Your prepared message", "courseOpenMail": "Open email app", "courseDraftNote": "This is a prepared message only. Open your email app, review the details and send it yourself. This page does not confirm delivery. If no email app opens, you can copy this message and send it yourself to info@mlinner-software.de.", "courseTo": "To", "courseSubject": "Subject", "courseEmailSubject": "Course – optional Excel contact list | Rendezora", "courseEmailGreeting": "Hello,", "courseEmailIntro": "Please include the following voluntarily provided details in our course contact list:", "courseEmailBye": "Best regards,", "courseRequired": "Please fill in this field.", "courseNeedLocation": "Please enter a town/postcode or choose to use GPS.", "courseGpsHelp": "Your browser will ask for permission. Check the coordinates before sending the email. You can remove them from this form at any time. Your location is not requested automatically.", "courseDataTitle": "What happens to my details?", "courseDataInfo": "These details are collected for our optional course contact list. By confirming, you allow all completed fields, including your address, GPS and “Other information”, to be included in an Excel file shared with the course group. The form first places your details in a local email draft; it does not automatically add them to the map or participant list. Closing this window clears the form fields. After sending, copies may remain in mailboxes and later with recipients of the Excel file. For questions or a deletion request, contact info@mlinner-software.de. Copies that have already been shared are not automatically recalled.", "courseEmail": "Email address", "coursePhone": "Phone / mobile", "courseStreet": "Street", "courseHouse": "House number", "coursePostal": "Postcode", "courseCountry": "Country", "courseOther": "Other information", "courseOtherHelp": "Add anything else you would like to share with the course group. Up to 1,000 characters.", "courseConsent": "I would like to join the optional Excel contact list. I agree that all details I enter here – including my address, GPS and “Other information”, where provided – may be shared with everyone in our course.", "courseConsentTitle": "Joining the contact list", "courseConsentHelp": "This box is not preselected. No message is prepared without your confirmation.", "courseNeedEntry": "Please enter at least one optional detail.", "courseNeedConsent": "Please confirm sharing within our course.", "courseConsentEmail": "Confirmation of inclusion and sharing"});
let language='de';
try{const saved=localStorage.getItem('rendezora-language');if(saved==='de'||saved==='en')language=saved;}catch{}
function t(key,vars={}){return (TEXT[language][key]||TEXT.de[key]||key).replace(/\{(\w+)\}/g,(_,name)=>vars[name]??`{${name}}`);}

// Kursangaben: ausschließlich ein lokaler E-Mail-Entwurf, kein Versand und keine Speicherung.
const COURSE_RECIPIENT='info@mlinner-software.de';
const COURSE_FIELDS=[['first','courseFirst'],['last','courseLast'],['email','courseEmail'],['phone','coursePhone'],['street','courseStreet'],['house','courseHouse'],['postal','coursePostal'],['town','courseTown'],['country','courseCountry'],['other','courseOther']];
let courseFormNotice=null;
let courseGps=null,courseGpsPending=false,courseGpsGeneration=0,courseGpsNotice=null;
function renderCourseGps(){
 $('course-gps').disabled=courseGpsPending;
 $('course-gps').textContent=t(courseGpsPending?'courseGpsLoading':'courseGpsButton');
 $('course-gps-clear').hidden=!courseGps;
 $('course-gps-output').hidden=!courseGps;
 $('course-gps-output').textContent=courseGps?`${Math.abs(courseGps.lat).toFixed(5)}° ${courseGps.lat<0?'S':'N'}, ${Math.abs(courseGps.lon).toFixed(5)}° ${courseGps.lon<0?'W':'E'}`+(Number.isFinite(courseGps.accuracy)?` · ${t('courseGpsAccuracy',{n:Math.round(courseGps.accuracy)})}`:''):'';
 $('course-gps-status').textContent=courseGpsNotice?t(courseGpsNotice):'';
}
function courseEmail(){
 const lines=[t('courseEmailGreeting'),'',t('courseEmailIntro'),''];
 for(const [id,key] of COURSE_FIELDS){
  const value=$('course-'+id).value.trim();
  if(value)lines.push(`${t(key)}: ${id==='other'?'\r\n':''}${value}`);
 }
 if(courseGps){
  lines.push(`GPS: ${courseGps.lat.toFixed(5)}, ${courseGps.lon.toFixed(5)}`);
  if(Number.isFinite(courseGps.accuracy))lines.push(t('courseGpsAccuracy',{n:Math.round(courseGps.accuracy)}));
 }
 lines.push('',t('courseConsentEmail')+':',t('courseConsent'),'',t('courseEmailBye'));
 const name=[$('course-first').value.trim(),$('course-last').value.trim()].filter(Boolean).join(' ');
 if(name)lines.push(name);
 return {subject:t('courseEmailSubject'),body:lines.join('\r\n')};
}

function renderCourseDraft(){
 const draft=courseEmail();
 $('course-draft').value=`${t('courseTo')}: ${COURSE_RECIPIENT}\n${t('courseSubject')}: ${draft.subject}\n\n${draft.body}`;
 $('course-mail-link').href=`mailto:${COURSE_RECIPIENT}?subject=${encodeURIComponent(draft.subject)}&body=${encodeURIComponent(draft.body)}`;
}
function refreshCourseLanguage(){
 if(!$('course-dialog'))return;
 renderCourseGps();
 if(!$('course-preview').hidden)renderCourseDraft();
 for(const element of $('course-form').elements)if(element.setCustomValidity)element.setCustomValidity('');
 $('course-form-status').textContent=courseFormNotice?t(courseFormNotice):'';
}
function initCourse(){
 const dialog=$('course-dialog'),form=$('course-form');form.noValidate=true;
 $('course-open').addEventListener('click',()=>dialog.showModal());
 function resetCourse(){
  courseGpsGeneration++;courseGps=null;courseGpsPending=false;courseGpsNotice=null;courseFormNotice=null;form.reset();
  for(const element of $('course-form').elements)if(element.setCustomValidity)element.setCustomValidity('');
 $('course-form-status').textContent=courseFormNotice?t(courseFormNotice):'';
  $('course-preview').hidden=true;$('course-draft').value='';$('course-mail-link').removeAttribute('href');renderCourseGps();
 }
 $('course-close').addEventListener('click',()=>{resetCourse();dialog.close();});
 dialog.addEventListener('cancel',resetCourse);
 dialog.addEventListener('close',()=>{if(!dialog.open)resetCourse();});
 form.addEventListener('input',event=>{
  if(event.target instanceof HTMLInputElement)event.target.setCustomValidity('');
  $('course-town').setCustomValidity('');courseFormNotice=null;$('course-form-status').textContent='';$('course-preview').hidden=true;
 });
 $('course-gps').addEventListener('click',()=>{
  if(!navigator.geolocation){courseGpsNotice='courseGpsUnavailable';renderCourseGps();return;}
  courseGpsPending=true;courseGpsNotice='courseGpsPrompt';const generation=++courseGpsGeneration;renderCourseGps();
  navigator.geolocation.getCurrentPosition(position=>{
   if(generation!==courseGpsGeneration||!dialog.open)return;
   const {latitude:lat,longitude:lon,accuracy}=position.coords;
   if(!Number.isFinite(lat)||!Number.isFinite(lon)||Math.abs(lat)>90||Math.abs(lon)>180){courseGpsNotice='courseGpsFailed';courseGpsPending=false;renderCourseGps();return;}
   courseGps={lat,lon,accuracy};courseGpsPending=false;courseGpsNotice='courseGpsSuccess';
   $('course-town').setCustomValidity('');courseFormNotice=null;$('course-form-status').textContent='';$('course-preview').hidden=true;renderCourseGps();
  },error=>{
   if(generation!==courseGpsGeneration||!dialog.open)return;
   courseGpsPending=false;courseGpsNotice=error.code===1?'courseGpsDenied':'courseGpsFailed';renderCourseGps();
  },{enableHighAccuracy:false,maximumAge:0,timeout:12000});
 });
 $('course-gps-clear').addEventListener('click',()=>{
  courseGpsGeneration++;courseGps=null;courseGpsPending=false;courseGpsNotice=null;$('course-preview').hidden=true;renderCourseGps();
 });
 form.addEventListener('submit',event=>{
  event.preventDefault();
  courseFormNotice=null;$('course-form-status').textContent='';
  $('course-consent').setCustomValidity($('course-consent').checked?'':t('courseNeedConsent'));
  if(!form.reportValidity())return;
  if(!courseGps&&!COURSE_FIELDS.some(([id])=>$('course-'+id).value.trim())){
   courseFormNotice='courseNeedEntry';$('course-form-status').textContent=t(courseFormNotice);return;
  }
  renderCourseDraft();$('course-preview').hidden=false;
  // Erst Vorschau, dann bewusster Klick auf den Mailto-Link. Kein automatischer Versand.
  $('course-preview').scrollIntoView({block:'nearest',behavior:'smooth'});
  $('course-mail-link').focus({preventScroll:true});
 });
 renderCourseGps();
 if(location.hash==='#kurs'||location.hash==='#course')dialog.showModal();
}

const COLORS=['#173D37','#A36713','#526A8F','#86566E'];
const $=id=>document.getElementById(id);
const km=n=>new Intl.NumberFormat(language==='de'?'de-DE':'en-GB',{maximumFractionDigits:1}).format(n)+' km';
const personName=p=>p.name.startsWith('Teilnehmer ')?t('participant',{id:p.name.split(' ')[1]}):p.name;
const homeName=p=>language==='en'&&p.city==='Mayen bei Koblenz'?'Mayen near Koblenz':p.city;
const cityName=city=>city.isCenter?t('centerName'):homeName(city);
let map,layers,offline,streets,layerControl,zoomControl,busy=false,comparisonState=null,lastResult=null,mapNotice=null;
let statusMessage={key:'initial',vars:{}};
const matrixCache=new Map();
function setStatus(key,vars={}){statusMessage={key,vars};$('status').textContent=t(key,vars);}
function showMapNotice(key){mapNotice=key;$('map-error').hidden=!key;if(key)$('map-error').textContent=t(key);}
function airDistance(a,b){
  const rad=x=>x*Math.PI/180;
  const s=Math.sin(rad(b.lat-a.lat)/2)**2+Math.cos(rad(a.lat))*Math.cos(rad(b.lat))*Math.sin(rad(b.lon-a.lon)/2)**2;
  return 6371*2*Math.asin(Math.sqrt(Math.min(1,s)));
}

// Deterministisches agglomeratives Clustering mit Ward-ähnlichem Distanzkriterium.
function clusterPeople(people,count){
  const cost=group=>group.reduce((sum,a,i)=>sum+group.slice(i+1).reduce((s,b)=>s+airDistance(a,b)**2,0),0)/group.length;
  let groups=people.map(p=>[p]);
  while(groups.length>count){
    let best={increase:Infinity};
    for(let i=0;i<groups.length;i++)for(let j=i+1;j<groups.length;j++){
      const increase=cost([...groups[i],...groups[j]])-cost(groups[i])-cost(groups[j]);
      if(increase<best.increase)best={i,j,increase};
    }
    groups[best.i]=[...groups[best.i],...groups[best.j]];
    groups.splice(best.j,1);
  }
  return groups.sort((a,b)=>Math.min(...a.map(p=>p.id))-Math.min(...b.map(p=>p.id)));
}

// Gleiche Gewichtung aller Teilnehmer: Schwerpunkt der Einheitsvektoren auf der Erdkugel.
// Eigene Berechnungsart, unabhängig vom Vergleich der Auto-Anfahrtskilometer.
function geographicCenter(people){
 let x=0,y=0,z=0;
 people.forEach(p=>{const lat=p.lat*Math.PI/180,lon=p.lon*Math.PI/180;x+=Math.cos(lat)*Math.cos(lon);y+=Math.cos(lat)*Math.sin(lon);z+=Math.sin(lat);});
 const center={lat:Math.atan2(z,Math.hypot(x,y))*180/Math.PI,lon:Math.atan2(y,x)*180/Math.PI};
 const nearest=REFERENCE_CITIES.reduce((a,b)=>airDistance(center,a)<airDistance(center,b)?a:b);
 return {...center,isCenter:true,reference:nearest.city,referenceDistance:airDistance(center,nearest)};
}
async function distanceMatrix(people,destinations){
 const key=JSON.stringify([people.map(p=>p.id),destinations.map(c=>[c.lat,c.lon])]);
 if(matrixCache.has(key))return matrixCache.get(key);
 const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),7000);
 try{
  const points=[...people,...destinations];
  const coords=points.map(p=>`${p.lon},${p.lat}`).join(';');
  const sources=people.map((_,i)=>i).join(';');
  const targets=destinations.map((_,i)=>i+people.length).join(';');
  const radiuses=points.map(()=>1000).join(';');
  const response=await fetch(`https://router.project-osrm.org/table/v1/driving/${coords}?sources=${sources}&destinations=${targets}&radiuses=${radiuses}&annotations=distance`,{signal:controller.signal});
  if(!response.ok)throw new Error('routing');
  const data=await response.json();
  if(data.code!=='Ok'||!Array.isArray(data.distances)||data.distances.length!==people.length||data.distances.some(row=>!Array.isArray(row)||row.length!==destinations.length||row.some(d=>!Number.isFinite(d)||d<0)))throw new Error('routing');
  const matrix={road:true,values:Object.fromEntries(people.map((p,i)=>[p.id,data.distances[i].map(m=>m/1000)]))};
  matrixCache.set(key,matrix);return matrix;
 }catch{throw new Error('routing');}finally{clearTimeout(timeout);}
}
function meetingResult(people,city,index,matrix){
 const distances=people.map(p=>matrix.values[p.id][index]);
 const max=Math.max(...distances),min=Math.min(...distances);
 return {people,city,distances,total:distances.reduce((a,b)=>a+b,0),max,min,spread:max-min};
}
function rankRoadMeetings(people,candidates,matrix){
 return candidates.map((city,i)=>meetingResult(people,city,i,matrix)).sort((a,b)=>matrix.objective==='fair'?a.max-b.max||a.spread-b.spread||a.total-b.total:a.total-b.total||a.max-b.max);
}
function centerDetails(city){
 return `${city.lat.toFixed(5)}° N, ${city.lon.toFixed(5)}° E`+(city.reference?`<br>${t('nearCity',{km:km(city.referenceDistance),city:city.reference})}`:'');
}
function selectedPeople(){return PARTICIPANTS.filter(p=>$('person-'+p.id).checked);}
function refreshCounters(){
 const n=selectedPeople().length;
 $('selection-count').textContent=t('selectedCount',{n,total:PARTICIPANTS.length});
 $('toggle-all').textContent=t(n===PARTICIPANTS.length?'selectNone':'selectAll');
 $('map-count').textContent=t('mapCount',{n});
}
function renderComparison(){
 const state=comparisonState;$('comparison').hidden=!state;
 if(!state){$('comparison').replaceChildren();return;}
 const criterion=t(state.matrix.objective==='fair'?'sortFair':'sortRoad');
 $('comparison').innerHTML=`<h3>${t('compareTitle')}</h3><p class="comparison-help">${t('compareHelp',{criterion})}</p>`+state.options.map((options,g)=>{
  const selected=state.selected[g];
  const row=(label,values,bold=false)=>`<tr><th scope="row">${label}</th>${values.map((value,i)=>`<td class="${i===selected?'chosen':''}">${bold?`<strong>${value}</strong>`:value}</td>`).join('')}</tr>`;
  return `<section class="comparison-group"><h4><span class="group-key" style="background:${COLORS[g]}"></span>${t('groupLabel',{n:g+1})} · ${t('peopleCount',{n:options[0].people.length})}</h4><div class="table-scroll" tabindex="0" role="region" aria-label="${t('compareCaption',{n:g+1})}"><table class="comparison-table"><caption class="sr-only">${t('compareCaption',{n:g+1})}</caption><thead><tr><th scope="col">${t('oneWay')}</th>${options.map((r,i)=>`<th scope="col" class="${i===selected?'chosen':''}"><span class="rank">${t('rank',{n:i+1})}</span><strong>${cityName(r.city)}</strong><button type="button" class="choose-meeting" data-group="${g}" data-rank="${i}" aria-pressed="${i===selected}">${t(i===selected?'onMapSelected':'showOnMap')}</button></th>`).join('')}</tr></thead><tbody>`
  +options[0].people.map((p,j)=>row(`${personName(p)}<small>${homeName(p)}</small>`,options.map(r=>km(r.distances[j])))).join('')
  +row(t('totalKm'),options.map(r=>km(r.total)),true)+row(t('maxKm'),options.map(r=>km(r.max)),true)+row(t('minKm'),options.map(r=>km(r.min)))+row(t('spreadKm'),options.map(r=>km(r.spread)))
  +`</tbody></table></div><p class="scroll-help">${t('scrollHelp')}</p></section>`;
 }).join('');
}
function renderResults(results,matrix,fitMap=true){
 lastResult={results,matrix};
 const geographic=matrix.objective==='geographic',fair=matrix.objective==='fair';
 const alternative=comparisonState?.selected.some(i=>i!==0),single=results.length===1;
 $('method').textContent=t(matrix.road?'roadLabel':'airLabel');
 let titleKey=geographic?(single?'geoTitle':'geoGroupsTitle'):fair?(single?'fairTitle':'fairGroupsTitle'):(single?'roadTitle':'roadGroupsTitle');
 if(alternative)titleKey=single?'chosenTitle':'chosenGroupsTitle';
 $('result-title').textContent=t(titleKey,{n:results.length,city:cityName(results[0].city)});
 if(geographic){
  setStatus('geoStatus');$('status').textContent+=' '+t(matrix.road?'geoRoad':'geoAir');
 }else setStatus('roadStatus',{count:matrix.candidateCount,criterion:t(fair?'fairCriterion':'roadCriterion')});
 $('summary').hidden=!!comparisonState;
 $('summary').innerHTML=comparisonState?'':results.map((r,i)=>`<div class="summary-card" style="--group:${COLORS[i]}"><small>${t('groupLabel',{n:i+1})} · ${t('peopleCount',{n:r.people.length})}</small><strong>${cityName(r.city)}</strong><small>${centerDetails(r.city)}</small><div class="geo-metrics"><span>${t('totalKm')}<b>${km(r.total)}</b></span><span>${t('maxKm')}<b>${km(r.max)}</b></span><span>${t('spreadKm')}<b>${km(r.spread)}</b></span></div><small>${t(matrix.road?'roadLabel':'airLabel')}</small></div>`).join('');
 $('result-body').innerHTML=comparisonState?'':results.map((r,i)=>r.people.map((p,j)=>`<tr><td><span class="group-key" style="background:${COLORS[i]}"></span>${i+1} · ${cityName(r.city)}</td><td>${personName(p)}</td><td>${homeName(p)}</td><td>${km(r.distances[j])}<br><small>${t(matrix.road?'roadShort':'airShort')}</small></td></tr>`).join('')).join('');
 $('result-table').hidden=!!comparisonState;$('detail-scroll-help').hidden=!!comparisonState;drawMap(results,matrix.road,fitMap);
}
function drawMap(results=null,road=true,fit=true){
 if(!map)return;layers.clearLayers();
 const selected=selectedPeople(),bounds=[];
 PARTICIPANTS.forEach(p=>{
  const group=results?.findIndex(r=>r.people.some(member=>member.id===p.id));
  const color=group>=0?COLORS[group]:COLORS[0],active=selected.some(s=>s.id===p.id);
  const result=group>=0?results[group]:null;
  const distance=result?result.distances[result.people.findIndex(member=>member.id===p.id)]:null;
  const travel=distance!==null?`<br>${km(distance)} · ${t(road?'roadShort':'airShort')} ${t('to')} ${cityName(result.city)}`:'';
  L.circleMarker([p.lat,p.lon],{radius:7,color:'#fff',weight:2,fillColor:active?color:'#9ba7a0',fillOpacity:active?1:.35}).bindPopup(`<strong>${personName(p)}</strong><br>${homeName(p)}${travel}`).addTo(layers);
  bounds.push([p.lat,p.lon]);
 });
 results?.forEach((r,i)=>{
  const color=COLORS[i],pos=[r.city.lat,r.city.lon];
  r.people.forEach(p=>L.polyline([[p.lat,p.lon],pos],{color,weight:2,opacity:.65,dashArray:'5 7',interactive:false}).addTo(layers));
  L.marker(pos,{zIndexOffset:1000,icon:L.divIcon({className:'',html:`<div class="meeting-pin" style="--group:${color}">${i+1}</div>`,iconSize:[33,33],iconAnchor:[16,16]})}).bindPopup(`<strong>${t('groupLabel',{n:i+1})}: ${cityName(r.city)}</strong><br>${centerDetails(r.city)}<br>${t('peopleCount',{n:r.people.length})} · ${km(r.total)} ${t('totalShort')}`).addTo(layers);
  bounds.push(pos);
 });
 if(fit)map.fitBounds(bounds,{padding:[35,35],maxZoom:8,animate:false});
}
function refreshMapControls(){
 if(!map)return;
 if(layerControl)layerControl.remove();
 layerControl=L.control.layers({[t('embedded')]:offline,[t('osm')]:streets},null,{collapsed:false}).addTo(map);
 const control=layerControl.getContainer();control.setAttribute('aria-label',t('mapLayers'));
 control.querySelector('.leaflet-control-layers-toggle')?.setAttribute('title',t('mapLayers'));
 for(const [selector,key] of [['.leaflet-control-zoom-in','zoomIn'],['.leaflet-control-zoom-out','zoomOut']]){
  const el=document.querySelector(selector);el?.setAttribute('title',t(key));el?.setAttribute('aria-label',t(key));
 }
 map.attributionControl.setPrefix('<a href="https://leafletjs.com">Leaflet</a>');
 const boundary=`${t('borders')}: <a href="https://www.naturalearthdata.com/">Natural Earth</a>`;
 if(map._rendezoraBoundary)map.attributionControl.removeAttribution(map._rendezoraBoundary);
 map.attributionControl.addAttribution(boundary);map._rendezoraBoundary=boundary;
 const old=streets.options.attribution;
 const next=`&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> ${t('contributors')}`;
 if(map.hasLayer(streets)){map.attributionControl.removeAttribution(old);map.attributionControl.addAttribution(next);}
 streets.options.attribution=next;
}
function clearResult(){
 if(busy)return;lastResult=null;comparisonState=null;renderComparison();
 $('summary').replaceChildren();$('result-body').replaceChildren();$('result-table').hidden=true;$('detail-scroll-help').hidden=true;
 $('result-title').textContent=t('readyTitle');$('method').textContent=t('ready');setStatus('changed');drawMap();
}
function applyLanguage(){
 document.documentElement.lang=language;document.title=t('pageTitle');
 document.querySelectorAll('[data-i18n]').forEach(el=>el.textContent=t(el.dataset.i18n));
 document.querySelectorAll('[data-i18n-aria]').forEach(el=>el.setAttribute('aria-label',t(el.dataset.i18nAria)));
 document.querySelectorAll('[data-language]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.language===language)));
 PARTICIPANTS.forEach(p=>{$('name-'+p.id).textContent=personName(p);$('home-'+p.id).textContent=homeName(p);});
 $('objective-help').textContent=t('help_'+$('objective').value);refreshCounters();refreshMapControls();
 if(lastResult){renderComparison();renderResults(lastResult.results,lastResult.matrix,false);}
 else{
  $('result-title').textContent=t(statusMessage.key==='errorRouting'?'errorTitle':'readyTitle');
  $('method').textContent=t(statusMessage.key==='errorRouting'?'missingRouting':'ready');
  $('status').textContent=t(statusMessage.key,statusMessage.vars);drawMap(null,true,false);
 }
 refreshCourseLanguage();
 $('calculate').innerHTML=`${t(busy?'calculating':'calculate')} <span aria-hidden="true">→</span>`;
 if(mapNotice)showMapNotice(mapNotice);
}
async function calculate(event){
 event?.preventDefault();if(busy)return;
 const people=selectedPeople(),mode=document.querySelector('input[name=mode]:checked').value;
 const count=Number($('group-count').value),objective=$('objective').value;
 if(!people.length){setStatus('errorEmpty');return;}
 if(mode==='individual'&&(people.length<2||people.length>4)){setStatus('errorIndividual');return;}
 if(mode==='groups'&&people.length<count){setStatus('errorGroups',{n:count});return;}
 clearResult();busy=true;
 const controls=[...document.querySelectorAll('#planner input, #planner button, #planner select, [data-language]')];
 controls.forEach(el=>el.disabled=true);$('planner').setAttribute('aria-busy','true');$('calculate').textContent=t('calculating');
 setStatus(objective==='geographic'?'loadingGeo':'loadingRoad');
 try{
  const groups=mode==='groups'?clusterPeople(people,count):[people];
  const centers=groups.map(geographicCenter),candidates=objective==='geographic'?centers:REFERENCE_CITIES;
  let matrix;
  try{matrix=await distanceMatrix(people,candidates);}catch(error){
   if(objective!=='geographic')throw error;
   matrix={road:false,values:Object.fromEntries(people.map(p=>[p.id,centers.map(c=>airDistance(p,c))]))};
  }
  matrix={...matrix,objective,candidateCount:candidates.length};
  let results;
  if(objective==='geographic')results=groups.map((group,i)=>meetingResult(group,centers[i],i,matrix));
  else{
   const options=groups.map(group=>rankRoadMeetings(group,candidates,matrix).slice(0,3));
   comparisonState={options,selected:groups.map(()=>0),matrix};results=options.map(options=>options[0]);
  }
  renderComparison();renderResults(results,matrix);
 }catch{
  $('result-title').textContent=t('errorTitle');$('method').textContent=t('missingRouting');setStatus('errorRouting');
 }finally{
  busy=false;controls.forEach(el=>el.disabled=false);$('planner').setAttribute('aria-busy','false');
  $('calculate').innerHTML=`${t('calculate')} <span aria-hidden="true">→</span>`;
 }
}
function init(){
 $('participants').innerHTML=PARTICIPANTS.map(p=>`<label class="person"><input type="checkbox" id="person-${p.id}" checked><span class="avatar" aria-hidden="true">${p.id<3?p.name.slice(0,2).toUpperCase():p.name.slice(-2)}</span><span><strong id="name-${p.id}"></strong><small id="home-${p.id}"></small></span></label>`).join('');
 if(typeof L!=='undefined'){
  map=L.map('map',{scrollWheelZoom:false,zoomControl:false}).setView([51,9],6);
  zoomControl=L.control.zoom({zoomInTitle:t('zoomIn'),zoomOutTitle:t('zoomOut')}).addTo(map);
  layers=L.layerGroup().addTo(map);offline=L.layerGroup().addTo(map);
  L.geoJSON(OFFLINE_COUNTRIES,{style:f=>({color:'#a9b7a2',weight:1.2,fillColor:f.properties.name==='Germany'?'#f7f8f3':'#e3eadc',fillOpacity:1})}).addTo(offline);
  const labels=[['Hamburg',53.551,9.994],['Berlin',52.52,13.405],['Hannover',52.376,9.732],['Kassel',51.313,9.48],['Frankfurt',50.111,8.682],['Köln',50.938,6.96],['Leipzig',51.34,12.375],['Stuttgart',48.775,9.183],['München',48.137,11.576],['Nürnberg',49.452,11.077]];
  labels.forEach(([name,lat,lon])=>L.marker([lat,lon],{interactive:false,icon:L.divIcon({className:'city-label',html:name,iconSize:[90,18],iconAnchor:[-5,9]})}).addTo(offline));
  streets=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap'});
  map.on('baselayerchange',e=>showMapNotice(e.layer===streets?'onlineNote':null));
  streets.on('tileerror',()=>{map.removeLayer(streets);if(!map.hasLayer(offline))offline.addTo(map);showMapNotice('tilesFailed');});
  if(typeof ResizeObserver!=='undefined'){
   let lastWidth=0;new ResizeObserver(entries=>{const width=entries[0].contentRect.width;if(Math.abs(width-lastWidth)>1){lastWidth=width;map.invalidateSize({pan:false});drawMap(lastResult?.results||null,lastResult?.matrix.road??true);}}).observe($('map'));
  }
 }else{$('map').hidden=true;showMapNotice('leafletFailed');}
 $('participants').addEventListener('change',()=>{refreshCounters();clearResult();});
 $('toggle-all').addEventListener('click',()=>{const all=selectedPeople().length===PARTICIPANTS.length;PARTICIPANTS.forEach(p=>$('person-'+p.id).checked=!all);refreshCounters();clearResult();});
 document.querySelectorAll('input[name=mode]').forEach(el=>el.addEventListener('change',()=>{$('group-control').hidden=el.value!=='groups';clearResult();}));
 $('objective').addEventListener('change',()=>{$('objective-help').textContent=t('help_'+$('objective').value);clearResult();});
 $('group-count').addEventListener('change',clearResult);
 document.querySelectorAll('[data-language]').forEach(el=>el.addEventListener('click',()=>{
  if(busy||language===el.dataset.language)return;language=el.dataset.language;
  try{localStorage.setItem('rendezora-language',language);}catch{}
  applyLanguage();
 }));
 $('comparison').addEventListener('click',event=>{
  const button=event.target.closest('.choose-meeting');if(!button||!comparisonState||busy)return;
  const group=Number(button.dataset.group),rank=Number(button.dataset.rank);comparisonState.selected[group]=rank;
  const selected=comparisonState.options.map((options,i)=>options[comparisonState.selected[i]]);
  renderComparison();renderResults(selected,comparisonState.matrix);
  $('comparison').querySelector(`[data-group="${group}"][data-rank="${rank}"]`)?.focus({preventScroll:true});
 });
 $('planner').addEventListener('submit',calculate);initCourse();applyLanguage();setStatus('initial');calculate();
}
init();
